const context = $('Build Journal Context').first().json;
const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Google Sheets journal write failed';
const retryConfig = context.config.retry || {};
const operation = context.operation;
const attempts = Number(operation.attempts || 1);
const maxAttempts = Math.max(1, Number(retryConfig.maxAttempts || 5));
const retryable = /(^|\D)429(\D|$)|rate limit|too many requests|timeout|timed out|ECONN|ECONNRESET|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|network|refused|offline|socket hang up|connection reset|connection refused|ENETUNREACH|EHOSTUNREACH|5\d\d/i.test(String(detail)) && attempts < maxAttempts;
const baseDelay = Math.max(1, Number(retryConfig.baseDelaySeconds || 30));
const maxDelay = Math.max(baseDelay, Number(retryConfig.maxDelaySeconds || 3600));
const retryAfterMatch = String(detail).match(/Retry-After:\s*([0-9]+)/i);
const retryAfterSeconds = retryAfterMatch ? Math.max(1, Number(retryAfterMatch[1])) : null;
const delaySeconds = retryAfterSeconds !== null ? Math.min(maxDelay, retryAfterSeconds) : Math.min(maxDelay, baseDelay * Math.pow(2, Math.max(0, attempts - 1)));
const jitterSeconds = retryAfterSeconds !== null ? 0 : Math.floor(delaySeconds * 0.2 * Math.random());
const retryAt = retryable ? new Date(Date.now() + (delaySeconds + jitterSeconds) * 1000).toISOString() : null;
const stateUpdate = {
  status: retryable ? 'retry_scheduled' : 'needs_reconciliation',
  journal_status: 'failed',
  journal_error: String(detail).slice(0, 1000),
  last_error: String(detail).slice(0, 1000),
  next_attempt_at: retryAt,
};
return [{
  json: {
    ...context,
    journal: { enabled: true, status: 'failed', error: String(detail).slice(0, 1000) },
    warnings: [...(context.warnings || []), 'journal_write_failed'],
    hasWarning: true,
    retryScheduled: retryable,
    needsReconciliation: !retryable,
    nextAttemptAt: retryAt,
    stateUpdate,
  },
}];

