const context = $input.first().json;
const { lead, meta, crm, config, operation } = context;
const journal = context.journal || { enabled: false, status: 'disabled' };
const notifications = context.notifications || { enabled: false, status: 'disabled', channels: [] };
const warnings = Array.isArray(context.warnings) ? [...context.warnings] : [];
const retryScheduled = Boolean(context.retryScheduled);
const needsReconciliation = Boolean(context.needsReconciliation);
const operationStatus = retryScheduled ? 'retry_scheduled' : needsReconciliation ? 'needs_reconciliation' : 'completed';
let status = crm.status === 'skipped' ? 'crm_skipped' : crm.status;
if (retryScheduled) status = 'retry_scheduled';
else if (needsReconciliation) status = 'needs_reconciliation';
const httpStatus = retryScheduled || needsReconciliation ? 202 : (crm.httpStatus || (crm.status === 'updated' ? 200 : crm.status === 'skipped' ? 202 : 201));
const saved = ['created', 'updated'].includes(crm.status) || journal.status === 'saved';
const notified = notifications.status === 'sent';
const response = {
  ok: crm.status !== 'failed',
  status,
  requestId: meta.requestId,
  operationId: operation ? operation.id : null,
  operationStatus,
  externalId: lead.externalId,
  receivedAt: meta.receivedAt,
  displayTime: meta.displayReceivedAt,
  saved,
  notified,
  retryAt: context.nextAttemptAt || null,
  crm: {
    provider: crm.provider,
    status: crm.status,
    contactId: crm.contactId || null,
    matchedBy: crm.matchedBy || null,
    matchCount: crm.matchCount || 0,
    reason: crm.reason || null,
  },
  journal: { enabled: journal.enabled, status: journal.status },
  notifications: {
    enabled: notifications.enabled,
    status: notifications.status,
    channels: notifications.channels || [],
    messageId: notifications.messageId || null,
  },
  warnings,
};
const stateUpdate = {
  status: operationStatus,
  response,
  next_attempt_at: context.nextAttemptAt || null,
  last_error: warnings.length ? warnings.join('; ') : null,
  crm_provider: crm.provider,
  crm_status: crm.status,
  crm_contact_id: crm.contactId || null,
  journal_status: journal.status,
  journal_error: journal.error || null,
  telegram_status: notifications.status,
  telegram_message_id: notifications.messageId || null,
  telegram_error: notifications.error || null,
};
return [{ json: { response, httpStatus, hasWarning: Boolean(context.hasWarning || retryScheduled || needsReconciliation), operationId: operation ? operation.id : null, stateUpdate } }];

const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Configuration error';
const requestId = $execution && $execution.id ? String($execution.id) : null;
return [{
  json: {
