}];

const validated = $('Validate Lead').first().json;
const config = validated.config;
const webhook = $('Lead Webhook').first().json;
const headers = webhook.headers || {};
const rawHeaderKey = headers['idempotency-key'] ?? headers['Idempotency-Key'] ?? '';
const headerKey = typeof rawHeaderKey === 'string' ? rawHeaderKey.trim() : String(rawHeaderKey || '').trim();
const rawOperationId = headers['x-operation-id'] ?? headers['X-Operation-Id'] ?? '';
const recovery = String(headers['x-recovery'] || '').toLowerCase() === '1';
const operationIdHeader = recovery && typeof rawOperationId === 'string' ? rawOperationId.trim() : '';
const idempotencyConfig = config.idempotency || {};
const retryConfig = config.retry || {};
let idempotencyKey = validated.lead.externalId || headerKey || null;
if (idempotencyConfig.enabled === false) idempotencyKey = null;
const significant = {
  name: validated.lead.name,
  email: validated.lead.email,
  phone: validated.lead.phone,
  source: validated.lead.source,
  message: validated.lead.message,
  externalId: validated.lead.externalId,
};
return [{
  json: {
    lead: validated.lead,
    meta: validated.meta,
    config,
    operationInput: {
      clientId: config.clientName || 'client',
      source: validated.lead.source || (config.source && config.source.defaultSource) || 'unknown',
      idempotencyKey,
      operationId: operationIdHeader || null,
      fingerprint: JSON.stringify(significant),
      rawPayload: webhook.body,
      recovery,
      maxAttempts: Math.max(1, Number(retryConfig.maxAttempts || 5)),
      processingTimeoutSeconds: Math.max(30, Number(retryConfig.processingTimeoutSeconds || 300)),
    },
  },
}];

const reserved = $input.first().json.result;
const base = $('Build Operation').first().json;
const operation = reserved && reserved.operation ? reserved.operation : null;
const outcome = reserved ? reserved.outcome : 'not_found';
let decision = 'process';
if (outcome === 'replay') decision = 'replay';
else if (outcome === 'conflict') decision = 'conflict';
else if (outcome === 'in_progress') decision = 'in_progress';
else if (outcome === 'max_attempts' || outcome === 'current') decision = 'terminal';
else if (outcome === 'not_found') decision = 'not_found';
return [{ json: { ...base, operation, decision, operationOutcome: outcome } }];

const ctx = $('Decide Operation').first().json;
const op = ctx.operation;
let httpStatus = 200;
let response;
if (ctx.decision === 'replay') {
  const stored = op && op.response ? op.response : {};
  response = { ...stored, ok: stored.ok ?? true, replayed: true, operationId: op ? op.id : null };
} else if (ctx.decision === 'conflict') {
  httpStatus = 409;
  response = { ok: false, error: 'idempotency_conflict', message: 'Idempotency key was already used with different lead data.', operationId: op ? op.id : null };
} else if (ctx.decision === 'in_progress') {
  httpStatus = 202;
  response = { ok: true, status: 'in_progress', operationId: op ? op.id : null, operationStatus: op ? op.status : null, retryAt: op ? op.next_attempt_at : null };
} else if (ctx.decision === 'not_found') {
  httpStatus = 404;
  response = { ok: false, error: 'operation_not_found', message: 'Recovery operation was not found.' };
} else {
  httpStatus = 200;
  response = {
    ok: op ? op.status !== 'failed' : false,
    status: op ? op.status : 'unknown',
    operationId: op ? op.id : null,
    crm: op ? { provider: op.crm_provider, status: op.crm_status, contactId: op.crm_contact_id } : null,
    journal: op ? { status: op.journal_status } : null,
    notifications: op ? { status: op.telegram_status } : null,
  };
}
return [{ json: { response, httpStatus } }];

